1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<style>
5	    /* === Labs Institute Design System === */
6	    /* Dark chrome aesthetic matching labs.institute */
7	
8	    .labs {
9	        --labs-black: #0a0a0a;
10	        --labs-dark: #111111;
11	        --labs-surface: #1a1a1a;
12	        --labs-surface-2: #222222;
13	        --labs-border: rgba(255,255,255,0.08);
14	        --labs-border-hover: rgba(255,255,255,0.15);
15	        --labs-chrome: linear-gradient(135deg, #c0c0c0, #e8e8e8, #a0a0a0);
16	        --labs-chrome-text: linear-gradient(90deg, #999, #ddd, #999);
17	        --labs-white: #f0f0f0;
18	        --labs-dim: #666;
19	        --labs-muted: #888;
20	        --labs-accent: #c0c0c0;
21	        --labs-gold: #c9a84c;
22	        --labs-green: #4ade80;
23	        --labs-red: #f87171;
24	        --labs-blue: #60a5fa;
25	        --labs-font: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
26	        --labs-mono: 'Consolas', 'Courier New', monospace;
27	        --labs-tracking: 0.18em;
28	        --labs-tracking-sm: 0.08em;
29	    }
30	
31	    .labs-page {
32	        padding: 0; margin: 0;
33	        background: var(--labs-black);
34	        min-height: 100vh;
35	        font-family: var(--labs-font);
36	        color: var(--labs-white);
37	    }
38	
39	    /* Header bar */
40	    .labs-topbar {
41	        display: flex; align-items: center; justify-content: space-between;
42	        padding: 20px 40px;
43	        border-bottom: 1px solid var(--labs-border);
44	        background: var(--labs-black);
45	        position: sticky; top: 0; z-index: 50;
46	    }
47	    .labs-brand {
48	        font-size: 0.72rem; font-weight: 700;
49	        letter-spacing: var(--labs-tracking);
50	        text-transform: uppercase;
51	        background: var(--labs-chrome-text);
52	        -webkit-background-clip: text; -webkit-text-fill-color: transparent;
53	        background-clip: text;
54	    }
55	    .labs-brand-sub {
56	        font-size: 0.55rem; color: var(--labs-dim);
57	        letter-spacing: var(--labs-tracking);
58	        text-transform: uppercase; margin-top: 2px;
59	    }
60	    .labs-topbar-right {
61	        font-size: 0.6rem; color: var(--labs-dim);
62	        letter-spacing: var(--labs-tracking-sm);
63	        text-transform: uppercase;
64	    }
65	
66	    /* Layout */
67	    .labs-layout { display: flex; max-width: 1200px; margin: 0 auto; }
68	
69	    /* Sidebar */
70	    .labs-nav {
71	        width: 220px; flex-shrink: 0; padding: 30px 20px;
72	        border-right: 1px solid var(--labs-border);
73	        position: sticky; top: 60px; align-self: flex-start;
74	        height: calc(100vh - 60px); overflow-y: auto;
75	    }
76	    .labs-nav-title {
77	        font-size: 0.55rem; font-weight: 700; color: var(--labs-dim);
78	        letter-spacing: var(--labs-tracking); text-transform: uppercase;
79	        margin-bottom: 16px;
80	    }
81	    .labs-nav-item {
82	        display: flex; align-items: center; gap: 10px;
83	        padding: 10px 14px; margin-bottom: 2px;
84	        font-size: 0.68rem; font-weight: 500; color: var(--labs-dim);
85	        letter-spacing: var(--labs-tracking-sm); text-transform: uppercase;
86	        cursor: pointer; border-radius: 6px; transition: all 0.15s;
87	        border-left: 2px solid transparent;
88	    }
89	    .labs-nav-item:hover { color: var(--labs-muted); background: rgba(255,255,255,0.02); }
90	    .labs-nav-item.active {
91	        color: var(--labs-white); border-left-color: var(--labs-accent);
92	        background: rgba(255,255,255,0.03);
93	    }
94	    .labs-nav-num {
95	        font-family: var(--labs-mono); font-size: 0.58rem;
96	        color: var(--labs-dim); width: 18px;
97	    }
98	    .labs-nav-item.active .labs-nav-num { color: var(--labs-accent); }
99	
100	    /* Main content */
101	    .labs-main {
102	        flex: 1; padding: 30px 40px; min-width: 0;
103	    }
104	
105	    /* Section blocks */
106	    .labs-section {
107	        margin-bottom: 40px;
108	        padding-bottom: 40px;
109	        border-bottom: 1px solid var(--labs-border);
110	    }
111	    .labs-section:last-child { border-bottom: none; }
112	
113	    .labs-section-hdr {
114	        display: flex; align-items: baseline; gap: 14px;
115	        margin-bottom: 6px;
116	    }
117	    .labs-section-num {
118	        font-family: var(--labs-mono); font-size: 0.65rem;
119	        color: var(--labs-dim); letter-spacing: 0.05em;
120	    }
121	    .labs-section-title {
122	        font-size: 0.78rem; font-weight: 700;
123	        letter-spacing: var(--labs-tracking);
124	        text-transform: uppercase; color: var(--labs-white);
125	    }
126	    .labs-section-desc {
127	        font-size: 0.7rem; color: var(--labs-dim); margin-bottom: 24px;
128	        letter-spacing: 0.02em; line-height: 1.6;
129	    }
130	
131	    /* Form elements */
132	    .labs-label {
133	        font-size: 0.6rem; font-weight: 700; color: var(--labs-muted);
134	        letter-spacing: var(--labs-tracking-sm); text-transform: uppercase;
135	        margin: 18px 0 6px; display: block;
136	    }
137	    .labs-label:first-child { margin-top: 0; }
138	    .labs-required::after { content: ' *'; color: var(--labs-red); font-size: 0.7em; }
139	    .labs-hint {
140	        font-size: 0.6rem; color: #555; margin-top: 4px;
141	        letter-spacing: 0.02em; font-style: italic;
142	    }
143	
144	    .labs-input, .labs-textarea, .labs-select {
145	        width: 100%; padding: 12px 16px;
146	        background: var(--labs-surface);
147	        border: 1px solid var(--labs-border);
148	        border-radius: 6px;
149	        color: var(--labs-white);
150	        font-size: 0.82rem; font-family: var(--labs-font);
151	        transition: border-color 0.15s;
152	        letter-spacing: 0.01em;
153	    }
154	    .labs-textarea { resize: vertical; min-height: 60px; line-height: 1.6; }
155	    .labs-select { cursor: pointer; }
156	    .labs-select option { background: var(--labs-dark); color: var(--labs-white); }
157	    .labs-input:focus, .labs-textarea:focus, .labs-select:focus {
158	        outline: none; border-color: var(--labs-accent);
159	        background: var(--labs-surface-2);
160	    }
161	
162	    .labs-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
163	    .labs-grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 14px; }
164	
165	    /* Autocomplete dropdown */
166	    .labs-suggest {
167	        position: relative;
168	    }
169	    .labs-suggest-list {
170	        position: absolute; top: 100%; left: 0; right: 0; z-index: 20;
171	        background: var(--labs-surface-2); border: 1px solid var(--labs-border-hover);
172	        border-radius: 6px; max-height: 180px; overflow-y: auto;
173	        display: none; margin-top: 2px;
174	        box-shadow: 0 8px 24px rgba(0,0,0,0.5);
175	    }
176	    .labs-suggest-list.open { display: block; }
177	    .labs-suggest-item {
178	        padding: 8px 14px; font-size: 0.75rem; color: var(--labs-muted);
179	        cursor: pointer; transition: background 0.1s;
180	    }
181	    .labs-suggest-item:hover {
182	        background: rgba(255,255,255,0.05); color: var(--labs-white);
183	    }
184	    .labs-suggest-item .suggest-cat {
185	        font-size: 0.58rem; color: var(--labs-dim);
186	        text-transform: uppercase; letter-spacing: 0.06em;
187	    }
188	
189	    /* Service cards */
190	    .labs-svc-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
191	    .labs-svc {
192	        background: var(--labs-surface); border: 1px solid var(--labs-border);
193	        border-radius: 8px; padding: 14px 16px; cursor: pointer;
194	        transition: all 0.15s;
195	    }
196	    .labs-svc:hover { border-color: var(--labs-border-hover); }
197	    .labs-svc.selected { border-color: var(--labs-accent); background: rgba(192,192,192,0.04); }
198	    .labs-svc-name {
199	        font-size: 0.72rem; font-weight: 700; color: var(--labs-white);
200	        letter-spacing: var(--labs-tracking-sm); text-transform: uppercase;
201	        margin-bottom: 4px;
202	    }
203	    .labs-svc-desc { font-size: 0.65rem; color: var(--labs-dim); }
204	    .labs-svc-bench {
205	        font-size: 0.58rem; color: var(--labs-gold);
206	        margin-top: 4px; font-style: italic;
207	    }
208	
209	    /* DJ card */
210	    .labs-dj {
211	        background: var(--labs-surface); border: 1px solid var(--labs-border);
212	        border-radius: 10px; padding: 20px; margin-bottom: 14px;
213	    }
214	    .labs-dj-hdr {
215	        display: flex; justify-content: space-between; align-items: center;
216	        margin-bottom: 16px; padding-bottom: 10px;
217	        border-bottom: 1px solid var(--labs-border);
218	    }
219	    .labs-dj-name {
220	        font-size: 0.82rem; font-weight: 700;
221	        letter-spacing: var(--labs-tracking-sm); text-transform: uppercase;
222	    }
223	    .labs-dj-remove {
224	        background: none; border: none; color: var(--labs-dim);
225	        cursor: pointer; font-size: 0.68rem; letter-spacing: 0.04em;
226	        text-transform: uppercase; transition: color 0.15s;
227	    }
228	    .labs-dj-remove:hover { color: var(--labs-red); }
229	
230	    /* KPI grid */
231	    .labs-kpi-grid {
232	        display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px;
233	        margin-top: 8px;
234	    }
235	    .labs-kpi {
236	        background: var(--labs-dark); border: 1px solid var(--labs-border);
237	        border-radius: 6px; padding: 10px; text-align: center;
238	    }
239	    .labs-kpi label {
240	        font-size: 0.55rem; color: var(--labs-dim); display: block;
241	        text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 4px;
242	    }
243	    .labs-kpi input {
244	        width: 100%; text-align: center; background: none; border: none;
245	        color: var(--labs-white); font-size: 0.88rem; font-weight: 700;
246	        font-family: var(--labs-mono); outline: none;
247	    }
248	    .labs-kpi-bench {
249	        font-size: 0.5rem; color: var(--labs-gold); margin-top: 2px;
250	        font-style: italic;
251	    }
252	
253	    /* Social row */
254	    .labs-social-row {
255	        display: grid; grid-template-columns: 110px 1fr; gap: 10px;
256	        margin-bottom: 6px; align-items: center;
257	    }
258	    .labs-social-label {
259	        font-size: 0.65rem; font-weight: 600; color: var(--labs-dim);
260	        text-transform: uppercase; letter-spacing: 0.04em;
261	    }
262	    .labs-social-label .importance {
263	        font-size: 0.5rem; padding: 1px 5px; border-radius: 4px;
264	        margin-left: 4px; font-weight: 700;
265	    }
266	    .importance-critical { background: rgba(192,192,192,0.12); color: var(--labs-accent); }
267	    .importance-high { background: rgba(96,165,250,0.12); color: var(--labs-blue); }
268	
269	    /* Buttons */
270	    .labs-btn {
271	        padding: 10px 24px; border-radius: 4px;
272	        font-size: 0.68rem; font-weight: 700; cursor: pointer;
273	        font-family: var(--labs-font); border: none;
274	        letter-spacing: var(--labs-tracking-sm); text-transform: uppercase;
275	        transition: all 0.15s; display: inline-flex; align-items: center; gap: 8px;
276	    }
277	    .labs-btn-chrome {
278	        background: var(--labs-chrome); color: var(--labs-black);
279	    }
280	    .labs-btn-chrome:hover { opacity: 0.9; }
281	    .labs-btn-outline {
282	        background: transparent; color: var(--labs-accent);
283	        border: 1px solid var(--labs-border);
284	    }
285	    .labs-btn-outline:hover { border-color: var(--labs-accent); }
286	    .labs-btn-sm { padding: 7px 16px; font-size: 0.62rem; }
287	
288	    /* Output */
289	    .labs-output {
290	        background: var(--labs-dark); border: 1px solid var(--labs-border);
291	        border-radius: 6px; padding: 16px;
292	        font-family: var(--labs-mono); font-size: 0.68rem;
293	        color: var(--labs-muted); line-height: 1.7;
294	        white-space: pre-wrap; max-height: 400px; overflow-y: auto;
295	    }
296	    .labs-gen-card {
297	        background: var(--labs-surface); border: 1px solid var(--labs-border);
298	        border-radius: 8px; padding: 14px 18px; margin-bottom: 8px;
299	    }
300	    .labs-gen-title {
301	        font-size: 0.65rem; font-weight: 700; color: var(--labs-accent);
302	        text-transform: uppercase; letter-spacing: var(--labs-tracking-sm);
303	        margin-bottom: 8px;
304	    }
305	    .labs-gen-list {
306	        font-size: 0.68rem; color: var(--labs-dim); line-height: 1.8;
307	        padding-left: 14px;
308	    }
309	
310	    /* Toast override for Labs style */
311	    .labs-page .toast {
312	        background: var(--labs-surface-2); border: 1px solid var(--labs-accent);
313	        color: var(--labs-white); font-size: 0.72rem; letter-spacing: 0.04em;
314	    }
315	
316	    @media (max-width: 900px) {
317	        .labs-layout { flex-direction: column; }
318	        .labs-nav {
319	            width: 100%; position: static; height: auto;
320	            border-right: none; border-bottom: 1px solid var(--labs-border);
321	            display: flex; overflow-x: auto; padding: 10px 20px; gap: 0;
322	        }
323	        .labs-nav-title { display: none; }
324	        .labs-nav-item { white-space: nowrap; border-left: none; padding: 8px 12px; }
325	        .labs-main { padding: 20px; }
326	        .labs-topbar { padding: 16px 20px; }
327	        .labs-grid-2, .labs-grid-3, .labs-svc-grid { grid-template-columns: 1fr; }
328	        .labs-kpi-grid { grid-template-columns: 1fr 1fr; }
329	    }
330	</style>
331	</head>
332	<body>
333	<div class="labs labs-page">
334	    <div class="labs-topbar">
335	        <div>
336	            <div class="labs-brand">LABS.INSTITUTE</div>
337	            <div class="labs-brand-sub">Site Content Builder</div>
338	        </div>
339	        <div class="labs-topbar-right">Founded For The Future</div>
340	    </div>
341	
342	    <div class="labs-layout">
343	        <div class="labs-nav" id="labs-nav">
344	            <div class="labs-nav-title">Sections</div>
345	        </div>
346	        <div class="labs-main" id="labs-main"></div>
347	    </div>
348	</div>
349	
350	<script>
351	(function() {
352	    'use strict';
353	
354	    var industry = null;
355	    var djCounter = 0;
356	    var selectedServices = {};
357	
358	    var SECTIONS = [
359	        { id: 'brand', num: '01', title: 'Brand Identity' , desc: 'Name, tagline, values, and the voice of the brand. This shapes every page.' },
360	        { id: 'vision', num: '02', title: 'Vision & Mission', desc: 'Where Labs Institute is going, what problem it solves, and what makes it different.' },
361	        { id: 'services', num: '03', title: 'Services', desc: 'What Labs Institute offers. Industry suggestions shown — select what applies.' },
362	        { id: 'roster', num: '04', title: 'Artist Roster', desc: 'DJ profiles with bios, socials, and progress KPIs. Each becomes a profile page.' },
363	        { id: 'proof', num: '05', title: 'Proof of Value', desc: 'KPIs, case studies, and testimonials that show what joining Labs means for an artist.' },
364	        { id: 'socials', num: '06', title: 'Social & Contact', desc: 'Company channels, contact info, and calls-to-action.' },
365	        { id: 'site', num: '07', title: 'Site Structure', desc: 'Pages, homepage sections, design references, and embedded content.' },
366	        { id: 'output', num: '08', title: 'Blueprint', desc: 'Generated site blueprint. Save to memory or copy as a development prompt.' },
367	    ];
368	
369	    function loadIndustry() {
370	        return fetch('/data/labs-industry.json').then(function(r) { return r.ok ? r.json() : null; }).catch(function() { return null; });
371	    }
372	
373	    function init() {
374	        loadIndustry().then(function(data) {
375	            industry = data || {};
376	            renderNav();
377	            renderSections();
378	            setupScrollSpy();
379	        });
380	    }
381	
382	    function renderNav() {
383	        var html = '<div class="labs-nav-title">Sections</div>';
384	        SECTIONS.forEach(function(s) {
385	            html += '<div class="labs-nav-item" data-section="' + s.id + '" onclick="scrollTo(\'' + s.id + '\')">' +
386	                '<span class="labs-nav-num">' + s.num + '</span>' + s.title + '</div>';
387	        });
388	        document.getElementById('labs-nav').innerHTML = html;
389	    }
390	
391	    function renderSections() {
392	        var h = '';
393	
394	        // 01 Brand
395	        h += secOpen('brand', '01', 'Brand Identity', SECTIONS[0].desc);
396	        h += inp('Company Name', 'inp-name', 'Labs Institute', true);
397	        h += inp('Primary Tagline', 'inp-tagline', 'Founded For The Future', true);
398	        h += inp('Secondary Tagline', 'inp-tagline2', 'A short pitch — e.g. "Artist management for the underground"');
399	        h += txt('Core Values', 'inp-values', 'One per line', true, 'Reputation\nTransparency\nReinvestment\nFamily\nValue', 5);
400	        h += txt('Brand Voice', 'inp-voice', 'How should the site sound?', false, '', 2);
401	        h += '<div class="labs-hint">e.g. Professional but underground. Confident, not corporate. Community-first.</div>';
402	        h += txt('Target Audience', 'inp-audience', 'Who is this site for?', true, '', 2);
403	        h += '<div class="labs-hint">e.g. Emerging DJs seeking management, promoters looking for talent, venues booking acts</div>';
404	        h += secClose();
405	
406	        // 02 Vision
407	        h += secOpen('vision', '02', 'Vision & Mission', SECTIONS[1].desc);
408	        h += txt('Vision', 'inp-vision', 'Long-term goal', true, '', 3);
409	        h += txt('Mission', 'inp-mission', 'What Labs does day-to-day', true, '', 3);
410	        h += txt('Origin Story', 'inp-origin', 'How and why Labs started — humanises the brand', false, '', 4);
411	        h += txt('What Problem Does Labs Solve?', 'inp-problem', 'The pain point for DJs', true, '', 3);
412	        h += '<div class="labs-hint">e.g. Talented DJs can\'t get exposure, fair contracts, or structured career development</div>';
413	        h += txt('What Makes Labs Different?', 'inp-diff', 'Your edge', true, '', 3);
414	        h += secClose();
415	
416	        // 03 Services
417	        h += secOpen('services', '03', 'Services', SECTIONS[2].desc);
418	        h += '<div class="labs-svc-grid" id="svc-grid"></div>';
419	        h += txt('Additional Services', 'inp-custom-svcs', 'Any not listed above, one per line', false, '', 2);
420	        h += txt('Pricing Model', 'inp-pricing', 'How services are priced', false, '', 2);
421	        h += '<div class="labs-hint">e.g. Commission-based (15-20%), retainer, per-event fee</div>';
422	        h += secClose();
423	
424	        // 04 Roster
425	        h += secOpen('roster', '04', 'Artist Roster', SECTIONS[3].desc);
426	        h += '<div id="dj-cards"></div>';
427	        h += '<button class="labs-btn labs-btn-outline labs-btn-sm" onclick="addDJ()">+ Add Artist</button>';
428	        h += secClose();
429	
430	        // 05 Proof
431	        h += secOpen('proof', '05', 'Proof of Value', SECTIONS[4].desc);
432	        h += txt('Headline KPIs', 'inp-kpis', 'Big numbers for the hero. One per line.', true, '', 5);
433	        h += '<div class="labs-hint">e.g. 12 Artists Managed / 150+ Gigs Booked / 3x Social Growth / £50K+ Revenue</div>';
434	        h += txt('Case Study', 'inp-case', 'One DJ\'s journey — before and after Labs', false, '', 4);
435	        h += txt('Testimonials', 'inp-testimonials', 'Quotes with attribution, one per line', false, '', 4);
436	        h += txt('Before/After Metrics', 'inp-ba-metrics', 'KPIs tracked per DJ to show progress', true, '', 4);
437	        h += '<div class="labs-hint">e.g. IG followers at join vs now / Monthly gigs / Paid ratio / Average fee / SC plays</div>';
438	        h += secClose();
439	
440	        // 06 Socials
441	        h += secOpen('socials', '06', 'Social & Contact', SECTIONS[5].desc);
442	        h += '<div id="social-fields"></div>';
443	        h += '<div class="labs-grid-2" style="margin-top:14px;">';
444	        h += '<div>' + inp('Email', 'social-email', 'Contact email', true) + '</div>';
445	        h += '<div>' + inp('Phone', 'social-phone', 'Contact number') + '</div>';
446	        h += '</div>';
447	        h += inp('CTA for Artists', 'inp-cta-artists', 'e.g. "Join the roster — apply now"');
448	        h += inp('CTA for Promoters', 'inp-cta-promo', 'e.g. "Book our artists for your next event"');
449	        h += secClose();
450	
451	        // 07 Site
452	        h += secOpen('site', '07', 'Site Structure', SECTIONS[6].desc);
453	        h += txt('Pages', 'inp-pages', 'One per line', true, 'Home\nAbout\nRoster\nServices\nEvents\nContact', 6);
454	        h += txt('Homepage Sections', 'inp-hero', 'Sections on the landing page, in order', false, 'Hero + tagline\nKPI bar\nFeatured artists\nServices overview\nLatest events\nTestimonials\nCTA', 7);
455	        h += txt('Design References', 'inp-design', 'Sites with a look/feel you like', false, '', 3);
456	        h += txt('Embedded Content', 'inp-embeds', 'What should be embedded?', false, '', 2);
457	        h += '<div class="labs-hint">e.g. SoundCloud player, Spotify playlist, Instagram feed, YouTube highlights</div>';
