711	    function buildPrompt(d) {
712	        var l = ['# Labs Institute — Marketing Site Blueprint', 'Generated: ' + new Date().toLocaleDateString('en-GB'), ''];
713	        l.push('## Brand'); l.push('- Name: ' + d.brand.name);
714	        if(d.brand.tagline) l.push('- Tagline: ' + d.brand.tagline);
715	        if(d.brand.values.length) l.push('- Values: ' + d.brand.values.join(' / '));
716	        if(d.brand.voice) l.push('- Voice: ' + d.brand.voice);
717	        if(d.brand.audience) l.push('- Audience: ' + d.brand.audience);
718	        l.push(''); l.push('## Vision');
719	        if(d.vision.vision) l.push('- Vision: ' + d.vision.vision);
720	        if(d.vision.mission) l.push('- Mission: ' + d.vision.mission);
721	        if(d.vision.problem) l.push('- Problem: ' + d.vision.problem);
722	        if(d.vision.differentiator) l.push('- Edge: ' + d.vision.differentiator);
723	        if(d.vision.origin) { l.push(''); l.push('### Origin'); l.push(d.vision.origin); }
724	        if(d.services.length) { l.push(''); l.push('## Services'); d.services.forEach(function(s){l.push('- '+s);}); if(d.pricing) l.push('- Pricing: '+d.pricing); }
725	        if(d.roster.length) { l.push(''); l.push('## Roster (' + d.roster.length + ')');
726	            d.roster.forEach(function(dj) {
727	                l.push(''); l.push('### ' + dj.name + ' (' + dj.tier + ')');
728	                if(dj.genres.length) l.push('- Genres: ' + dj.genres.join(', '));
729	                if(dj.bio) l.push('- Bio: ' + dj.bio);
730	                var k=dj.kpis; if(k.gigs) l.push('- KPIs: '+k.gigs+' gigs ('+k.paid+' paid), avg £'+k.fee+', IG '+k.ig_join+'→'+k.ig+', SC '+k.sc_join+'→'+k.sc+', '+k.releases+' releases');
731	                if(dj.highlights) l.push('- Highlights: '+dj.highlights);
732	            });
733	        }
734	        if(d.proof.headline_kpis.length) { l.push(''); l.push('## Proof'); d.proof.headline_kpis.forEach(function(k){l.push('- '+k);}); }
735	        if(d.proof.case_study) { l.push('### Case Study'); l.push(d.proof.case_study); }
736	        if(Object.keys(d.socials).length) { l.push(''); l.push('## Socials'); Object.keys(d.socials).forEach(function(k){l.push('- '+k+': '+d.socials[k]);}); }
737	        if(d.site.pages.length) { l.push(''); l.push('## Site'); l.push('### Pages'); d.site.pages.forEach(function(p){l.push('- '+p);}); }
738	        if(d.site.hero.length) { l.push('### Homepage'); d.site.hero.forEach(function(s){l.push('- '+s);}); }
739	        return l.join('\n');
740	    }
